```python
def max_liste(l):
    if not l:
        return None
    maximum = l[0]
    for element in l:
        if element > maximum:
            maximum = element
    return maximum
```

```python
def fizzbuzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result
```

