```python
def facteur(n):
    if n == 0 or n == 1:
        return 1
    resultat = 1
    for i in range(2, n + 1):
        resultat *= i
    return resultat
```

```python
def tri_bulles(l):
    n = len(l)
    for i in range(n):
        for j in range(0, n - i - 1):
            if l[j] > l[j + 1]:
                l[j], l[j + 1] = l[j + 1], l[j]
    return l
```

```python
def fib(n):
    if n <= 1:
        return n
    a, b = 0, 1
    for i in range(2, n + 1):
        a, b = b, a + b
    return b
```

```python
def verifier_ip(s):
    if not isinstance(s, str):
        return False
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == '0':
            return False
        num = int(part)
        if num < 0 or num > 255:
            return False
    return True
```

```python
def freq_chars(s):
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1
    return freq
```

```python
def convertir_octets(n):
    if n < 1024:
        return f"{n} octets"
    elif n < 1024 * 1024:
        return f"{n / 1024:.2f} Ko"
    elif n < 1024 * 1024 * 1024:
        return f"{n / (1024 * 1024):.2f} Mo"
    else:
        return f"{n / (1024 * 1024 * 1024):.2f} Go"
```

