```python
def lire_csv(texte):
    lignes = texte.strip().split('\n')
    dico = {}
    for ligne in lignes:
        if ',' in ligne:
            cle, valeur = ligne.split(',', 1)
            dico[cle] = valeur
    return dico
```

```python
def dichotomie(l, x):
    gauche, droit = 0, len(l) - 1
    while gauche <= droit:
        milieu = (gauche + droit) // 2
        if l[midile] == x:
            return milieu
        elif l[midile] < x:
            gauche = milieu + 1
        else:
            droit = milieu - 1
    return -1
```

