```python
def supprimer_doublons(l):
    vues = set()
    resultat = []
    for element in l:
        if element not in vues:
            resultat.append(element)
            vues.add(element)
    return resultat
```

```python
def est_premier(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True
```
